function openPanel(type){if(panelType===type&&!$('#panel').hidden){closePanel();return;}panelType=type;$('#panel').hidden=false;$('#panel-title').textContent=({color:'颜色',brush:'像素笔刷',layers:'图层',export:'保存与导出',settings:'画室设置',animation:'动画设置'})[type];({color:colorPanel,brush:brushPanel,layers:layersPanel,export:exportPanel,settings:settingsPanel,animation:animationPanel})[type]();}
function closePanel(){$('#panel').hidden=true;panelType='';}$('#close-panel').onclick=closePanel;$$('[data-panel]').forEach(b=>b.onclick=()=>openPanel(b.dataset.panel));
function colorPanel(){ $('#panel-content').innerHTML=`<div class="color-picker"><input type="color" id="picker" aria-label="选择颜色" value="${color}"><input id="hex-color" aria-label="十六进制颜色" value="${color}" maxlength="7"></div><p class="palette-heading">雨巷 · 32 色调色板</p><div class="palette">${palette.map(c=>`<button class="swatch ${c===color?'active':''}" style="background:${c}" data-color="${c}" aria-label="颜色 ${c}"></button>`).join('')}</div><p class="help">点击吸管工具，从画布中拾取颜色。按住 I 也可切换到吸管。</p>`;$('#picker').oninput=e=>{color=e.target.value;$('#hex-color').value=color;refresh();};$('#hex-color').onchange=e=>{if(/^#[0-9a-f]{6}$/i.test(e.target.value)){color=e.target.value;$('#picker').value=color;refresh();}else{e.target.value=color;toast('输入格式如 #ef87a0');}};$$('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;colorPanel();refresh();});}
function brushPanel(){ $('#panel-content').innerHTML=`<label>笔刷大小 <span id="size-value" class="row-value">${size} px</span><input id="size-range" type="range" min="1" max="32" value="${size}"></label><label>笔尖形状<select id="brush-shape"><option value="square">方形 · 硬边像素</option><option value="round">圆形 · 硬边像素</option><option value="dither">棋盘 · 抖色</option><option value="custom">自定义 · 8 × 8 笔尖</option></select></label><label class="switch">笔压控制大小<input type="checkbox" id="pressure" ${pressure?'checked':''}></label><p class="help">仅对触控笔生效；1 px 笔刷保持单像素。浏览器收到的压力值决定笔尖大小。</p><p class="palette-heading">自定义笔尖 · 轻点格子编辑</p><div class="brush-grid">${customMask.map((v,i)=>`<button data-mask="${i}" class="${v?'on':''}" aria-label="笔尖像素 ${i+1}" aria-pressed="${!!v}"></button>`).join('')}</div><div class="brush-chips"><button id="mask-square">实心</button><button id="mask-cross">十字</button><button id="mask-clear">清空</button></div><button id="use-custom" class="panel-wide">使用并保存这个笔尖</button>`;$('#brush-shape').value=shape;$('#brush-shape').onchange=e=>shape=e.target.value;$('#size-range').oninput=e=>{size=Number(e.target.value);$('#size-value').textContent=size+' px';$('#brush-size').textContent=size+' px';};$('#pressure').onchange=e=>{pressure=e.target.checked;settingsSave();};$$('[data-mask]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.mask);customMask[i]^=1;b.classList.toggle('on',!!customMask[i]);b.setAttribute('aria-pressed',!!customMask[i]);settingsSave();});$('#mask-square').onclick=()=>{customMask.fill(1);settingsSave();brushPanel();};$('#mask-cross').onclick=()=>{customMask=customMask.map((_,i)=>i%8===3||Math.floor(i/8)===3?1:0);settingsSave();brushPanel();};$('#mask-clear').onclick=()=>{customMask.fill(0);settingsSave();brushPanel();};$('#use-custom').onclick=()=>{if(!customMask.some(Boolean)){toast('请至少保留一个笔尖像素');return;}shape='custom';size=Math.max(8,size);settingsSave();refresh();brushPanel();toast('自定义笔尖已保存在此设备');};}
function layersPanel(){const c=$('#panel-content');c.innerHTML=`<div id="layer-list"></div><div class="button-row"><button id="add-layer">＋ 图层</button><button id="rename-layer">重命名</button></div><label>透明度 <span class="row-value" id="opacity-value">${Math.round(project.layers[layer].opacity/255*100)}%</span><input id="opacity" type="range" min="0" max="255" value="${project.layers[layer].opacity}"></label><div class="button-row"><button id="layer-up">上移</button><button id="layer-down">下移</button><button id="delete-layer" class="danger">删除</button></div><p class="help">从上到下显示图层顺序。新图层会为每一帧创建空白单元，编辑只影响当前帧。</p>`;
 for(let i=project.layers.length-1;i>=0;i--){const l=project.layers[i],row=document.createElement('div');row.className='layer'+(i===layer?' active':'');row.innerHTML=`<button class="visibility" aria-label="${l.visible?'隐藏':'显示'}图层 ${esc(l.name)}">${svg(l.visible?'eye':'hidden')}</button><button class="layer-select" aria-label="选择图层 ${esc(l.name)}"><span>${esc(l.name)}</span></button>`;const t=document.createElement('canvas');paintBuffer(t,project.frames[frame].cels[i]);row.querySelector('.layer-select').prepend(t);row.querySelector('.visibility').onclick=()=>{checkpoint();l.visible=!l.visible;changed();};row.querySelector('.layer-select').onclick=()=>{layer=i;layersPanel();};$('#layer-list').append(row);}
 $('#add-layer').onclick=()=>{if(!capacity(project.layers.length+1,project.frames.length))return;stop();checkpoint();project.layers.push({name:'图层 '+(project.layers.length+1),visible:true,opacity:255});project.frames.forEach(f=>f.cels.push(new Uint8ClampedArray(project.w*project.h*4)));layer=project.layers.length-1;changed();};$('#rename-layer').onclick=()=>{const name=prompt('图层名称',project.layers[layer].name);if(name?.trim()){checkpoint();project.layers[layer].name=name.trim().slice(0,160);changed();}};$('#opacity').onchange=e=>{checkpoint();project.layers[layer].opacity=Number(e.target.value);changed();};$('#opacity').oninput=e=>$('#opacity-value').textContent=Math.round(e.target.value/255*100)+'%';
 const reorder=delta=>{const dest=layer+delta;if(dest<0||dest>=project.layers.length)return;checkpoint();[project.layers[layer],project.layers[dest]]=[project.layers[dest],project.layers[layer]];project.frames.forEach(f=>[f.cels[layer],f.cels[dest]]=[f.cels[dest],f.cels[layer]]);layer=dest;changed();};$('#layer-up').onclick=()=>reorder(1);$('#layer-down').onclick=()=>reorder(-1);$('#layer-up').disabled=layer===project.layers.length-1;$('#layer-down').disabled=layer===0;$('#delete-layer').disabled=project.layers.length===1;$('#delete-layer').onclick=()=>{if(!confirm('删除当前图层及所有帧上的内容？可以撤销。'))return;checkpoint();project.layers.splice(layer,1);project.frames.forEach(f=>f.cels.splice(layer,1));layer=Math.max(0,layer-1);changed();};
}
function animationPanel(){$('#panel-content').innerHTML=`<label>当前帧时长（毫秒）<input id="duration" type="number" min="20" max="10000" value="${project.frames[frame].duration}"></label><button id="duration-all" class="panel-wide">将此时长应用到所有帧</button><button id="delete-frame" class="panel-wide danger">删除当前帧</button><p class="help">120 ms 约为每秒 8 帧。底部 ＋ 添加空白帧，重叠方框复制当前帧；洋葱皮显示前一帧的淡影。</p>`;$('#duration').onchange=e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<20||n>10000){toast('帧时长范围：20–10000 毫秒');e.target.value=project.frames[frame].duration;return;}stop();checkpoint();project.frames[frame].duration=n;changed();};$('#duration-all').onclick=()=>{stop();checkpoint();const d=project.frames[frame].duration;project.frames.forEach(f=>f.duration=d);changed();toast('所有帧时长已统一');};$('#delete-frame').disabled=project.frames.length===1;$('#delete-frame').onclick=()=>{if(!confirm('删除当前帧？可以撤销。'))return;stop();checkpoint();project.frames.splice(frame,1);frame=Math.min(frame,project.frames.length-1);changed();animationPanel();};}
function settingsPanel(){$('#panel-content').innerHTML=`<label class="switch">仅 Apple Pencil / 触控笔绘画<input id="pen-setting" type="checkbox" ${penOnly?'checked':''}></label><div class="note-box">开启后，手指只用于移动、缩放、旋转和撤销。识别到笔正在绘画时，会忽略手指落点；压感和防误触的实际效果请在 iPad 验证。</div><div class="shortcut-table"><b>双指轻点</b><span>撤销</span><b>三指轻点</b><span>重做</span><b>双指拖动 / 捏合</b><span>移动 / 缩放</span><b>双指旋转</b><span>旋转画布</span><b>B / E / I / G</b><span>画笔 / 橡皮 / 吸管 / 填色</span><b>⌘ / Ctrl + Z</b><span>撤销</span><b>Space</b><span>播放 / 暂停</span></div><button id="install-help" class="panel-wide">安装到 iPad 主屏幕</button><button id="manual-save" class="panel-wide">立即保存到作品库</button><p class="help">像素画室 v0.1 · 网页版<br>画布最大 512 × 512；普通图层与逐帧动画。Apple Pencil 双击、挤压等硬件快捷手势暂未接入。</p>`;$('#pen-setting').onchange=e=>{penOnly=e.target.checked;settingsSave();refresh();};$('#install-help').onclick=()=>toast('在 iPad 的 Safari 打开线上地址 → 分享 → 添加到主屏幕。首次打开后可离线绘画。');$('#manual-save').onclick=async()=>{if(await saveCurrent())toast('已保存到本地作品库');};}
function download(data,ext,type){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=project.name.replace(/[\\/:*?"<>|]/g,'_')+ext;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('已生成文件，请在浏览器下载中查看');}
function exportPanel(){$('#panel-content').innerHTML=`<p class="help">项目备份保留所有像素、图层和动画；导出后可在「文件」中保存或传到其他设备。</p><button id="export-project" class="panel-wide">${svg('export')}画室项目 .pixel</button><button id="export-ase" class="panel-wide">${svg('layers')}Aseprite .aseprite</button><button id="export-png" class="panel-wide">当前帧 · PNG 透明图片</button><button id="export-sheet" class="panel-wide">全部帧 · PNG 横向精灵图</button><button id="export-gif" class="panel-wide">动画 · GIF</button><button id="export-import" class="panel-wide">导入项目 / Aseprite / 图片</button><p class="help">Aseprite：普通 RGBA 图层与帧时长。导入兼容 RGB、灰度、索引色与压缩单元；特殊混合模式、图层分组与瓦片需先转换。GIF 使用 216 色量化，半透明像素转为透明或不透明。</p>`;$('#export-project').onclick=()=>download(serialize(project),'.pixel','application/json');$('#export-ase').onclick=()=>download(writeAse(project),'.aseprite','application/octet-stream');$('#export-png').onclick=()=>thumb(project,frame).toBlob(b=>download(b,'.png'),'image/png');$('#export-sheet').onclick=()=>{if(project.w*project.frames.length>16384){toast('精灵图过宽，请减少帧数或使用 Aseprite 导出');return;}const c=document.createElement('canvas');c.width=project.w*project.frames.length;c.height=project.h;const x=c.getContext('2d');project.frames.forEach((_,i)=>x.drawImage(thumb(project,i),i*project.w,0));c.toBlob(b=>download(b,'-sheet.png'),'image/png');};$('#export-gif').onclick=()=>download(encodeGif(project),'.gif','image/gif');$('#export-import').onclick=()=>$('#file-input').click();}
// IndexedDB stores complete projects; saves are queued so an older write cannot win.
function request(req){return new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function openDB(){const req=indexedDB.open('pixel-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'id'});db=await request(req);}
async function storeRecord(record){return new Promise((resolve,reject)=>{const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(record);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function saveCurrent(){const p=clone(project),key=id,v=dirtyVersion;saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{if(!db)throw Error('本地存储不可用');const c=thumb(p,0),preview=c.toDataURL('image/png');await storeRecord({id:key,project:p,preview,updated:Date.now()});try{localStorage.setItem('pixel-studio-current',key);}catch{}if(key===id&&v===dirtyVersion){savedVersion=v;$('#save-status').textContent='已保存在此设备';}return true;}catch(e){$('#save-status').textContent='保存失败，请导出备份';toast('本地保存失败，请导出 .pixel 文件备份');return false;}});return saveQueue;}
async function loadProject(p,key=crypto.randomUUID()){validate(p);if(stroke)return;stop();clearTimeout(saveTimer);if(savedVersion!==dirtyVersion)await saveCurrent();project=p;id=key;frame=0;layer=p.layers.length-1;undoStack=[];redoStack=[];historyBytes=0;dirtyVersion=0;savedVersion=-1;closePanel();$('#gallery-dialog').close();fit();refresh();await saveCurrent();}
async function gallery(){if(stroke)return;stop();await saveCurrent();$('#gallery-dialog').showModal();try{const list=await request(db.transaction('projects').objectStore('projects').getAll());list.sort((a,b)=>b.updated-a.updated);$('#gallery-list').innerHTML='';for(const r of list){const card=document.createElement('div');card.className='project-card';card.innerHTML=`<button class="project-open" aria-label="打开 ${esc(r.project.name)}"><img alt="${esc(r.project.name)}预览" src="${r.preview}"><div class="project-meta"><strong>${esc(r.project.name)}</strong><span>${r.project.w} × ${r.project.h} · ${r.project.frames.length} 帧</span></div></button><button class="delete-project" aria-label="删除 ${esc(r.project.name)}">×</button>`;card.querySelector('.project-open').onclick=()=>loadProject(clone(r.project),r.id);card.querySelector('.delete-project').onclick=async()=>{if(r.id===id){toast('当前作品请先切换到另一作品再删除');return;}if(confirm(`从此设备删除「${r.project.name}」？`)){await request(db.transaction('projects','readwrite').objectStore('projects').delete(r.id));card.remove();}};$('#gallery-list').append(card);}}catch{ $('#gallery-list').innerHTML='<p class="empty-gallery">作品库暂不可用，请用「保存与导出」备份当前作品。</p>';}}
$('#gallery').onclick=gallery;$('#close-gallery').onclick=()=>$('#gallery-dialog').close();$('#new-project').onclick=()=>$('#new-dialog').showModal();$('#cancel-new').onclick=()=>$('#new-dialog').close();$$('[data-size]').forEach(b=>b.onclick=()=>{$('#new-form [name=width]').value=b.dataset.size;$('#new-form [name=height]').value=b.dataset.size;});$('#new-form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),p=blank(Number(data.get('width')),Number(data.get('height')),String(data.get('name')).trim()||'未命名作品');$('#new-dialog').close();await loadProject(p);};$('#new-demo').onclick=()=>loadProject(demo());$('#import-button').onclick=()=>$('#file-input').click();
$('#file-input').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>60*1024*1024){toast('文件超过 60 MB，请先缩小项目');return;}try{let p,warnings=[];if(/\.(ase|aseprite)$/i.test(file.name)){const result=await readAse(await file.arrayBuffer());p=result.project;warnings=result.warnings;}else if(/\.(pixel|json)$/i.test(file.name))p=deserialize(await file.text());else{const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.naturalWidth>512||img.naturalHeight>512)throw Error('图片最大 512 × 512，请先缩小图片');p=blank(img.naturalWidth,img.naturalHeight);const c=document.createElement('canvas');c.width=p.w;c.height=p.h;const x=c.getContext('2d');x.drawImage(img,0,0);p.frames[0].cels[0]=x.getImageData(0,0,p.w,p.h).data;}finally{URL.revokeObjectURL(url);}}p.name=file.name.replace(/\.[^.]+$/,'').slice(0,160);await loadProject(p);toast(warnings.length?'已导入：'+warnings.join('；'):'已导入 '+file.name);}catch(err){toast(err.message||'文件导入失败');}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('dialog[open]'))return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if((e.ctrlKey||e.metaKey)&&key==='s'){e.preventDefault();saveCurrent();}else if(e.code==='Space'){e.preventDefault();$('#play').click();}else if(key==='escape')closePanel();else if(({b:'pencil',e:'eraser',i:'pick',g:'fill',h:'hand',l:'line',r:'rect'})[key]){tool=({b:'pencil',e:'eraser',i:'pick',g:'fill',h:'hand',l:'line',r:'rect'})[key];refresh();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();if(stroke){if(!stroke.pan)project=stroke.before;stroke=null;pointers.clear();penActive=false;gesture=null;touchBatch=null;render();}saveCurrent();}});window.addEventListener('beforeunload',e=>{if(savedVersion!==dirtyVersion){e.preventDefault();e.returnValue='';}});
async function init(){toolsBuild();resize();fit();refresh();try{await openDB();const key=localStorage.getItem('pixel-studio-current');if(key){const record=await request(db.transaction('projects').objectStore('projects').get(key));if(record){project=validate(record.project);id=key;layer=project.layers.length-1;fit();refresh();}}await saveCurrent();}catch(e){toast('浏览器存储不可用，请通过导出备份作品');}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('离线缓存暂未启用，联网时仍可正常绘画'));}
init();
